require_once dirname(__DIR__).'/includes/admin_helpers.php';exigirAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_validar();$id=(int)($_POST['id']??0);$acao=(string)($_POST['acao']??'');if($id>0&&in_array($acao,['aberta','encerrada','excluir'],true)){if($acao==='excluir'){$s=$conexao->prepare('DELETE FROM vagas WHERE id=?');$s->bind_param('i',$id);}else{$s=$conexao->prepare('UPDATE vagas SET status=? WHERE id=?');$s->bind_param('si',$acao,$id);}if($s->execute())adminLog($conexao,$acao,'vaga',$id);$s->close();}header('Location: vagas.php');exit;}
adminHeader('Gerenciar vagas');$r=$conexao->query('SELECT v.id,v.titulo,v.status,e.nome_empresa FROM vagas v LEFT JOIN empresas e ON e.id=v.empresa_id ORDER BY v.id DESC');echo '<div style="overflow:auto"><table><thead><tr><th>Vaga</th><th>Empresa</th><th>Status</th><th>Ações</th></tr></thead><tbody>';while($v=$r->fetch_assoc()){echo '<tr><td>'.e($v['titulo']).'</td><td>'.e($v['nome_empresa']??'').'</td><td>'.e($v['status']).'</td><td>';foreach(['aberta'=>'Abrir','encerrada'=>'Encerrar','excluir'=>'Excluir'] as $a=>$rot){echo '<form method="post" style="display:inline"'.($a==='excluir'?' onsubmit="return confirm(\'Excluir esta vaga?\')"':'').'><input type="hidden" name="id" value="'.(int)$v['id'].'"><input type="hidden" name="acao" value="'.$a.'">';csrf_campo();echo '<button>'.$rot.'</button></form> ';}echo '</td></tr>'; }echo '</tbody></table></div>';adminFooter();
